/** Дописать две сцены: шаги в конец, цель, 20 минут, +55 XP и +25 Złotki за длину. */
export function withSwietaScenes(list: Mission[]): Mission[] {
  return list.map((m) => {
    const sc = SCENES_SWIETA[m.slug];
    if (!sc) return m;
    return { ...m, goal: sc.goal, steps: [...m.steps, ...sc.steps], minutes: SWIETA_MINUTES, xp: m.xp + 55, zlotki: m.zlotki + 25 };
  });
}
